{
  "category_edits": [
    {
      "category": "feature_construction",
      "rationale": "Apply the supplied mild frequency-confidence feature across all four datasets: scale history inputs by 1+0.01*log1p(training_count)/log1p(max_training_count). Counts use only training interactions. Persist scales as a model buffer, preserve zero padding and candidate embeddings, and synchronize predictor validation. Learned parameters, GRU topology, readout, loss and optimizer remain unchanged.",
      "edits": [
        {
          "find": "        self.item_emb = UnitNormItemEmbedding(itemnum + 1, hidden_units, padding_idx=0)\n        dropout = dropout_rate if num_layers > 1 else 0.0",
          "replace": "        self.item_emb = UnitNormItemEmbedding(itemnum + 1, hidden_units, padding_idx=0)\n        self.register_buffer(\"history_input_scales\", torch.ones(itemnum + 1))\n        self.history_input_scales[0] = 0.0\n        dropout = dropout_rate if num_layers > 1 else 0.0"
        },
        {
          "find": "        emb = self.dropout(self.item_emb(seq))",
          "replace": "        emb = self.dropout(\n            self.item_emb(seq) * self.history_input_scales[seq].unsqueeze(-1)\n        )"
        },
        {
          "find": "    ).to(device)\n    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)",
          "replace": "    ).to(device)\n    training_counts = np.zeros(itemnum + 1, dtype=np.int64)\n    for history in user_train.values():\n        np.add.at(training_counts, np.asarray(history, dtype=np.int64), 1)\n    training_counts[0] = 0\n    log_counts = np.log1p(training_counts.astype(np.float64))\n    max_log_count = float(log_counts.max())\n    history_scales = np.ones(itemnum + 1, dtype=np.float32)\n    if max_log_count > 0.0:\n        history_scales += (0.01 * log_counts / max_log_count).astype(np.float32)\n    history_scales[0] = 0.0\n    with torch.no_grad():\n        model.history_input_scales.copy_(torch.as_tensor(history_scales, device=device))\n    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)"
        },
        {
          "find": "            \"sequence_readout\": \"gru_0.8_causal_mean_0.2_half_life_3\",\n",
          "replace": "            \"sequence_readout\": \"gru_0.8_causal_mean_0.2_half_life_3\",\n            \"history_input_feature\": \"train_log_frequency_amplification_0.01\",\n"
        },
        {
          "find": "        model = ModelClass(\n            itemnum=meta[\"itemnum\"],",
          "replace": "        if meta.get(\"history_input_feature\") != \"train_log_frequency_amplification_0.01\":\n            raise RuntimeError(f\"Incompatible GRU history input feature for {ds}\")\n        model = ModelClass(\n            itemnum=meta[\"itemnum\"],"
        }
      ]
    }
  ],
  "change_summary": "Add training-only frequency scaling to history embeddings, checkpoint the fixed scales, and validate the feature in the embedded predictor. Preserve all four independent category models and existing training settings."
}
